use std::collections::HashMap;
fn two_sum(values: &[i32], target: i32) -> Option<(usize, usize)> {
    let mut seen = HashMap::new();
    for (j, &value) in values.iter().enumerate() {
        let needed = i64::from(target) - i64::from(value);
        if let Some(&i) = seen.get(&needed) { return Some((i, j)); }
        seen.entry(i64::from(value)).or_insert(j);
    }
    None
}
fn main() {
    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));
    assert_eq!(two_sum(&[3], 6), None);
}

